  public static void validateErrorDetail(Anthropic.ErrorDetail msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate type (assert_required)
    if (msg.getType().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field type is required");
    }
    // Validate type (assert_max_length: 64)
    if (msg.getType().length() > 64) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field type must be at most 64 characters, got: %d", msg.getType().length()));
    }
    // Validate message (assert_required)
    if (msg.getMessage().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field message is required");
    }
    // Validate message (assert_max_length: 4096)
    if (msg.getMessage().length() > 4096) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field message must be at most 4096 characters, got: %d", msg.getMessage().length()));
    }
  }

  public static void validateProxyEvent(Anthropic.ProxyEvent msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate subject (assert_required)
    if (msg.getSubject().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field subject is required");
    }
    // Validate subject (assert_min_length: 1)
    if (msg.getSubject().length() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field subject must be at least 1 characters, got: %d", msg.getSubject().length()));
    }
    // Validate subject (assert_max_length: 256)
    if (msg.getSubject().length() > 256) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field subject must be at most 256 characters, got: %d", msg.getSubject().length()));
    }
    // Validate requestEpochMs (assert_ge: 0)
    if (msg.getRequestEpochMs() < 0L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field requestEpochMs must be >= 0, got: %s", msg.getRequestEpochMs()));
    }
    // Validate responseEpochMs (assert_ge: 0)
    if (msg.getResponseEpochMs() < 0L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field responseEpochMs must be >= 0, got: %s", msg.getResponseEpochMs()));
    }
    // Validate durationMs (assert_ge: 0)
    if (msg.getDurationMs() < 0L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field durationMs must be >= 0, got: %s", msg.getDurationMs()));
    }
    // Validate upstreamStatus (assert_ge: 100)
    if (msg.getUpstreamStatus() < 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field upstreamStatus must be >= 100, got: %s", msg.getUpstreamStatus()));
    }
    // Validate upstreamStatus (assert_le: 599)
    if (msg.getUpstreamStatus() > 599) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field upstreamStatus must be <= 599, got: %s", msg.getUpstreamStatus()));
    }
    // Validate provider (assert_max_length: 64)
    if (msg.getProvider().length() > 64) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field provider must be at most 64 characters, got: %d", msg.getProvider().length()));
    }
  }

