  public static Anthropic.ProxyEvent.Builder mergeProxyEvent(
      Anthropic.ProxyEvent dst, Anthropic.ProxyEvent src) {
    Anthropic.ProxyEvent.Builder builder = dst.toBuilder();
    if (dst.getSubject().isEmpty()) {
      builder.setSubject(src.getSubject());
    }
    if (!dst.hasRequest() && src.hasRequest()) {
      builder.setRequest(src.getRequest());
    } else if (dst.hasRequest() && src.hasRequest()) {
      builder.setRequest(mergeCreateMessageRequest(dst.getRequest(), src.getRequest()).build());
    }
    if (!dst.hasResponse() && src.hasResponse()) {
      builder.setResponse(src.getResponse());
    } else if (dst.hasResponse() && src.hasResponse()) {
      builder.setResponse(mergeCreateMessageResponse(dst.getResponse(), src.getResponse()).build());
    }
    if (!dst.hasError() && src.hasError()) {
      builder.setError(src.getError());
    } else if (dst.hasError() && src.hasError()) {
      builder.setError(mergeErrorResponse(dst.getError(), src.getError()).build());
    }
    if (dst.getRequestEpochMs() == 0) {
      builder.setRequestEpochMs(src.getRequestEpochMs());
    }
    if (dst.getResponseEpochMs() == 0) {
      builder.setResponseEpochMs(src.getResponseEpochMs());
    }
    if (dst.getDurationMs() == 0) {
      builder.setDurationMs(src.getDurationMs());
    }
    if (!dst.getStreamed()) {
      builder.setStreamed(src.getStreamed());
    }
    if (dst.getUpstreamStatus() == 0) {
      builder.setUpstreamStatus(src.getUpstreamStatus());
    }
    if (dst.getProvider().isEmpty()) {
      builder.setProvider(src.getProvider());
    }
    return builder;
  }

