  public static Map<String, String> streamEventToEnvVar(Anthropic.StreamEvent msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_STREAM_EVENT_TYPE", streamEventTypeToString(msg.getType()));
    if (msg.hasMessage()) {
      result.putAll(createMessageResponseToEnvVar(msg.getMessage()));
    }
    result.put("PROTO_STREAM_EVENT_INDEX", String.valueOf(msg.getIndex()));
    if (msg.hasContentBlock()) {
      result.putAll(contentBlockToEnvVar(msg.getContentBlock()));
    }
    if (msg.hasDelta()) {
      result.putAll(streamDeltaToEnvVar(msg.getDelta()));
    }
    if (msg.hasUsage()) {
      result.putAll(usageToEnvVar(msg.getUsage()));
    }
    return result;
  }

