  public static Map<String, String> proxyEventToEnvVar(Anthropic.ProxyEvent msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_PROXY_EVENT_SUBJECT", msg.getSubject());
    if (msg.hasRequest()) {
      result.putAll(createMessageRequestToEnvVar(msg.getRequest()));
    }
    if (msg.hasResponse()) {
      result.putAll(createMessageResponseToEnvVar(msg.getResponse()));
    }
    if (msg.hasError()) {
      result.putAll(errorResponseToEnvVar(msg.getError()));
    }
    result.put("PROTO_PROXY_EVENT_REQUEST_EPOCH_MS", String.valueOf(msg.getRequestEpochMs()));
    result.put("PROTO_PROXY_EVENT_RESPONSE_EPOCH_MS", String.valueOf(msg.getResponseEpochMs()));
    result.put("PROTO_PROXY_EVENT_DURATION_MS", String.valueOf(msg.getDurationMs()));
    result.put("PROTO_PROXY_EVENT_STREAMED", String.valueOf(msg.getStreamed()));
    result.put("PROTO_PROXY_EVENT_UPSTREAM_STATUS", String.valueOf(msg.getUpstreamStatus()));
    result.put("PROTO_PROXY_EVENT_PROVIDER", msg.getProvider());
    return result;
  }

  public static Anthropic.ProxyEvent.Builder proxyEventFromEnvVar(Map<String, String> env) {
    Anthropic.ProxyEvent.Builder builder = Anthropic.ProxyEvent.newBuilder();
    String val;
    val = env.get("PROTO_PROXY_EVENT_SUBJECT");
    if (val != null && !val.isEmpty()) {
      builder.setSubject(val);
    }
    {
      var sub = createMessageRequestFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setRequest(sub);
      }
    }
    {
      var sub = createMessageResponseFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setResponse(sub);
      }
    }
    {
      var sub = errorResponseFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setError(sub);
      }
    }
    val = env.get("PROTO_PROXY_EVENT_REQUEST_EPOCH_MS");
    if (val != null && !val.isEmpty()) {
      builder.setRequestEpochMs(Long.parseLong(val));
    }
    val = env.get("PROTO_PROXY_EVENT_RESPONSE_EPOCH_MS");
    if (val != null && !val.isEmpty()) {
      builder.setResponseEpochMs(Long.parseLong(val));
    }
    val = env.get("PROTO_PROXY_EVENT_DURATION_MS");
    if (val != null && !val.isEmpty()) {
      builder.setDurationMs(Long.parseLong(val));
    }
    val = env.get("PROTO_PROXY_EVENT_STREAMED");
    if (val != null && !val.isEmpty()) {
      builder.setStreamed(Boolean.parseBoolean(val));
    }
    val = env.get("PROTO_PROXY_EVENT_UPSTREAM_STATUS");
    if (val != null && !val.isEmpty()) {
      builder.setUpstreamStatus(Integer.parseInt(val));
    }
    val = env.get("PROTO_PROXY_EVENT_PROVIDER");
    if (val != null && !val.isEmpty()) {
      builder.setProvider(val);
    }
    return builder;
  }

